fn complete_arg_value(
    value: Result<&str, &OsStr>,
    arg: &clap::Arg,
    current_dir: Option<&std::path::Path>,
    arg_index: usize,
) -> Vec<CompletionCandidate> {
    let mut values = Vec::new();
    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");

    let (prefix, value) =
        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));

    let value_os = match value {
        Ok(value) => OsStr::new(value),
        Err(value_os) => value_os,
    };

    // For delimited, bounded multi-value arguments, complete the value as a
    // sequence of comma-separated segments: already entered segments must name
    // known candidates, and only candidates not used earlier in *this*
    // occurrence are offered.  Any malformed input (empty segment, unknown
    // segment, too many segments) yields no candidates.
    let delimiter = arg.get_value_delimiter();
    let full_value = match (delimiter, value) {
        (Some(delimiter), Ok(_)) => Some((delimiter, prefix.is_some())),
        _ => None,
    };
    if let Some((delimiter, has_prefix)) = full_value {
        let range = arg.get_num_args().expect("built");
        let bounded_multi = (1..usize::MAX).contains(&range.max_values());
        if bounded_multi {
            if let Some(delimited) =
                complete_delimited_arg_value(value_os, arg, current_dir, arg_index, delimiter)
            {
                values = delimited;
            } else if !has_prefix {
                complete_single_arg_value(&mut values, value_os, arg, current_dir, arg_index);
            }
        } else {
            complete_single_arg_value(&mut values, value_os, arg, current_dir, arg_index);
        }
    } else {
        complete_single_arg_value(&mut values, value_os, arg, current_dir, arg_index);
    }

    if let Some(prefix) = prefix {
        values = values
            .into_iter()
            .map(|comp| comp.add_prefix(prefix))
            .collect();
    }
    values = values
        .into_iter()
        .map(|comp| {
            if comp.get_tag().is_some() {
                comp
            } else {
                comp.tag(Some(arg.to_string().into()))
            }
        })
        .collect();

    debug!("complete_arg_value: values={values:?}");
    values
}

/// Complete the (last, possibly empty) segment of a delimiter-separated value.
///
/// Returns `None` when the argument does not admit this kind of completion
/// (open-ended candidate set), leaving the caller to fall back to the legacy
/// behavior; an empty `Vec` means the input is invalid and must not complete
/// to anything.
fn complete_delimited_arg_value(
    value_os: &OsStr,
    arg: &clap::Arg,
    current_dir: Option<&std::path::Path>,
    arg_index: usize,
    delimiter: char,
) -> Option<Vec<CompletionCandidate>> {
    let value = value_os.to_str()?;
    // The typed text always ends at a delimiter boundary: `rsplit_delimiter`
    // hands us the segment after the last delimiter, and `prefix` (everything
    // up to and including that delimiter) is preserved verbatim.
    let mut segments: Vec<&str> = if value.is_empty() {
        Vec::new()
    } else {
        value.split(delimiter).collect()
    };
    // A trailing delimiter means a new empty segment is being entered.
    let trailing_delim = value_os.ends_with(delimiter.encode_utf8(&mut [0; 4]));
    if trailing_delim {
        segments.push("");
    }

    let max_values = arg.get_num_args().expect("built").max_values();
    // The segment under the cursor does not count as committed yet.
    let committed = segments.len().saturating_sub(1);
    if committed > max_values {
        return Some(Vec::new());
    }

    let mut completed = Vec::new();
    if let Some(completer) = arg.get::<ArgValueCompleter>() {
        // A dynamic completer cannot be enumerated to validate committed
        // segments, so fall back to completing the current segment only.
        let current = segments.last().copied().unwrap_or("");
        completed = completer.complete_at(arg_index, OsStr::new(current));
    } else if let Some(candidates) = arg.get::<ArgValueCandidates>() {
        let pool = candidates.candidates();
        let mut iter = pool.into_iter();
        complete_delimited_segments(&segments, &mut iter, max_values, &mut completed)?;
    } else if let Some(possible_values) = possible_values(arg) {
        let mut iter = possible_value_candidates(possible_values).into_iter();
        complete_delimited_segments(&segments, &mut iter, max_values, &mut completed)?;
    } else {
        // Paths and other open-ended hints cannot be validated segment by
        // segment; let the caller handle them.
        let _ = current_dir;
        return None;
    }

    Some(completed)
}

/// Validate committed segments and build candidates for the segment under the
/// cursor.
///
/// Returns `None` when the candidate iterator cannot be fully enumerated in a
/// way that lets us validate committed segments (dynamic candidates); an empty
/// completion set is expressed through `completed` instead.
fn complete_delimited_segments<I>(
    segments: &[&str],
    candidates: &mut I,
    max_values: usize,
    completed: &mut Vec<CompletionCandidate>,
) -> Option<()>
where
    I: Iterator<Item = CompletionCandidate>,
{
    let pool: Vec<CompletionCandidate> = candidates.collect();
    let current = segments.last().copied().unwrap_or("");
    let committed = &segments[..segments.len().saturating_sub(1)];

    // Every committed segment must name a candidate that is still unused at
    // that point; segments are matched in definition order but must be unique
    // within one occurrence.
    let mut used: Vec<&str> = Vec::with_capacity(committed.len());
    for segment in committed {
        if segment.is_empty() {
            // A consecutive delimiter (or a leading one) creates an empty
            // segment, which is never valid.
            return Some(());
        }
        let matched = pool
            .iter()
            .find(|c| c.get_value() == OsStr::new(segment))
            .map(|c| c.get_value().to_str().map(str::to_owned));
        match matched {
            Some(Ok(name)) if !used.contains(&name.as_str()) => {
                used.push(name.leak_static());
            }
            _ => return Some(()),
        }
    }
    if segments.len().saturating_sub(1) > max_values {
        return Some(());
    }

    for candidate in &pool {
        let name = match candidate.get_value().to_str() {
            Some(name) => name,
            None => continue,
        };
        if used.iter().any(|u| *u == name) {
            continue;
        }
        if !name.starts_with(current) {
            continue;
        }
        // Only suggest a value when it still fits within the per-occurrence
        // bound; the current segment occupies one of the slots.
        if segments.len() > max_values {
            continue;
        }
        completed.push(candidate.clone());
    }
    Some(())
}

fn complete_single_arg_value(
    values: &mut Vec<CompletionCandidate>,
    value_os: &OsStr,
    arg: &clap::Arg,
    current_dir: Option<&std::path::Path>,
    arg_index: usize,
) {
    let value = value_os.to_str();
    if let Some(completer) = arg.get::<ArgValueCompleter>() {
        values.extend(completer.complete_at(arg_index, value_os));
    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
        values.extend(complete_value_candidates(
            value_os,
            completer.value_candidates(),
        ));
    } else if let Some(possible_values) = possible_values(arg) {
        if let Ok(value) = value {
            values.extend(complete_candidates_str(
                value,
                possible_value_candidates(possible_values),
            ));
        }
    } else {
        match arg.get_value_hint() {
            clap::ValueHint::Unknown | clap::ValueHint::Other => {
                // Should not complete
            }
            clap::ValueHint::AnyPath => {
                values.extend(complete_path(value_os, current_dir, &|_| true));
            }
            clap::ValueHint::FilePath => {
                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
            }
            clap::ValueHint::DirPath => {
                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
            }
            clap::ValueHint::ExecutablePath => {
                use is_executable::IsExecutable;
                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
            }
            clap::ValueHint::CommandName
            | clap::ValueHint::CommandString
            | clap::ValueHint::CommandWithArguments
            | clap::ValueHint::Username
            | clap::ValueHint::Hostname
            | clap::ValueHint::Url
            | clap::ValueHint::EmailAddress => {
                // No completion implementation
            }
            _ => {
                // Safe-ish fallback
                values.extend(complete_path(value_os, current_dir, &|_| true));
            }
        }

        values.sort();
    }
}

fn rsplit_delimiter<'s, 'o>(
    value: Result<&'s str, &'o OsStr>,
    delimiter: Option<char>,
) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
    let delimiter = delimiter?;
    let value = value.ok()?;
    let pos = value.rfind(delimiter)?;
    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
    Some((Some(prefix), Ok(value)))
}

