/// completed and re-prefixed with everything typed before it.
fn complete_legacy_arg_value(
    values: &mut Vec<CompletionCandidate>,
    value: Result<&str, &OsStr>,
    arg: &clap::Arg,
    current_dir: Option<&std::path::Path>,
    arg_index: usize,
    delimiter: char,
) {
