dev,ci
"#]],
        );

        // An attached short flag follows the same rules.
        assert_data_eq!(
            complete!(cmd, format!("{invocation} -tdev,[TAB]")),
            snapbox::str![[r#"
-tdev,prod
-tdev,ci
"#]],
        );

        // The occurrence may carry at most two values.
        assert_data_eq!(
            complete!(cmd, format!("{invocation} --tag=dev,ci,[TAB]")),
            snapbox::str![""]
